export const controle = {
    criados: 0,
    geracoes: 0,
    resposta: 'Hm. Deixa eu pensar.',
    atrasoMs: 0,
    falharAoCriar: false,
    ultimoModelo: undefined,
    ultimasOpcoes: undefined,
    ultimasMensagens: undefined,
    ultimosParams: undefined,
    reset() {
        this.criados = 0;
        this.geracoes = 0;
        this.resposta = 'Hm. Deixa eu pensar.';
        this.atrasoMs = 0;
        this.falharAoCriar = false;
        this.ultimoModelo = undefined;
        this.ultimasOpcoes = undefined;
        this.ultimasMensagens = undefined;
        this.ultimosParams = undefined;
    },
};

export const env = {};

export async function pipeline(_tarefa, modelo, opcoes) {
    controle.criados += 1;
    controle.ultimoModelo = modelo;
    controle.ultimasOpcoes = opcoes;
    if (controle.falharAoCriar) throw new Error('CDN fake indisponível');

    opcoes?.progress_callback?.({
        status: 'progress',
        file: 'model_quantized.onnx',
        loaded: 100,
        total: 100,
    });

    return async (mensagens, params) => {
        controle.geracoes += 1;
        controle.ultimasMensagens = mensagens;
        controle.ultimosParams = params;
        if (controle.atrasoMs > 0) {
            await new Promise((resolve) => setTimeout(resolve, controle.atrasoMs));
        }
        return [{
            generated_text: [
                ...mensagens,
                { role: 'assistant', content: controle.resposta },
            ],
        }];
    };
}
